# Prüft Statusanzeige, Ablaufübersicht und den ausdrücklich ausgelösten Diagnoseexport mit echten Browser-APIs.
import argparse
from browser_realtime import check_pages
from check_work_report_layout import STATIC
ASSETS=['messages.js','quality-ui.js']
def fixture():
 setup=r'''localStorage.clear();history.replaceState(null,'','/tf/arbeitsbericht');window.I18n={t:s=>s,locale:'de-DE'};window.AndroidPortal={version:Promise.resolve('0.28.12.16'),offline:{inspect:async()=>({jobs:[],reports:[]})}};let tracks=[];window.GpsRecorder={pendingTransfers:async()=>tracks};let download=null;AndroidPortal.saveBlob=async(name,blob)=>download={name,text:await blob.text()};let own=11;window.fetch=async url=>String(url).includes('/account/me')?new Response(JSON.stringify({id:11,role:'tf',username:'787117'})):new Response(JSON.stringify({owner_id:own,counts:{valid:1,expiring:1,expired:1,missing:1},total:4,items:[{kind:'places',id:1,name:'Testort',valid_until:'2026-11-22',state:'expired'},{kind:'routes',id:2,name:'Teststrecke',valid_until:'2027-01-01',state:'expiring'},{kind:'classes',id:3,name:'BR 185',valid_until:'',state:'missing'}]}));'''
 checks=r'''
(async()=>{const assert=(v,m)=>{if(!v)throw Error(m);},wait=()=>new Promise(r=>setTimeout(r,25)),until=async fn=>{const end=performance.now()+10000;while(!fn()){if(performance.now()>end)throw Error('Timeout');await wait();}};
 const report={client_id:'synthetic-report',start_at:'2026-11-23T08:00',end_at:'2026-11-23T16:00',train_journeys:[]};localStorage.setItem('lokzeitleiste.work-report.11.pending',JSON.stringify([report]));
 RailQuality.setOwner(11);RailQuality.status('work_reports','synthetic-report','local');await until(()=>document.querySelector('[data-quality-status]').dataset.syncState==='local');
 AndroidPortal.offline.inspect=async()=>({jobs:[],reports:[{id:'synthetic-report',blocked:false}]});RailQuality.status('work_reports','synthetic-report','queued');await until(()=>document.querySelector('[data-quality-status]').dataset.syncState==='queued');
 RailQuality.status('work_reports','synthetic-report','review',{message:'PRIVATE_PERSONAL_TEXT',issues:[{loc:['body','train_journeys',0,'events',0,'cause']}]});AndroidPortal.offline.inspect=async()=>({jobs:[],reports:[]});RailQuality.status('work_reports','synthetic-report','local');await until(()=>document.querySelector('[data-quality-status]').dataset.syncState==='review');assert(RailQuality.read()[0].repair.message==='PRIVATE_PERSONAL_TEXT','Background local update cannot erase a correction');
 document.querySelector('[data-quality-status] button').click();await until(()=>document.querySelector('dialog li button'));let opened=null;window.WorkReportNavigation={open:async(id,repair,journey)=>opened={id,repair,journey}};const row=document.querySelector('dialog li');assert(row.textContent.includes('23.11.2026 08:00'),'Report date identifies the actual report');row.querySelector('button').click();await until(()=>opened);assert(opened.id==='synthetic-report'&&opened.repair.issues.length===1,'Status opens the precise failed report with field metadata');
 // Veraltete Statusmetadaten dürfen keine erledigten Aufträge wieder sichtbar machen.
 localStorage.removeItem('lokzeitleiste.work-report.11.pending');dispatchEvent(new Event('quality-sync-change'));await until(()=>document.querySelector('[data-quality-status]').dataset.syncState==='synced');RailQuality.setOwner(12);assert(RailQuality.read().length===0,'Status metadata is bound to its TF');assert(document.querySelector('[data-quality-status] button:nth-child(2)').hidden,'Diagnostics hidden for a different account');RailQuality.setOwner(11);
 localStorage.setItem('lokzeitleiste.work-report.11',JSON.stringify({client_id:'gps-report',train_journeys:[{id:'gps-track'}]}));tracks=[{journey_id:'gps-track',dirty:true,ended:true,train_number:'456',start:Date.parse('2026-11-22T09:00:00Z')}];dispatchEvent(new Event('quality-sync-change'));await until(()=>document.querySelector('[data-quality-status]').dataset.syncState==='queued');document.querySelector('[data-quality-status] button').click();await until(()=>document.querySelector('dialog li button'));const gpsRow=document.querySelector('dialog li');assert(gpsRow.textContent.includes('456')&&gpsRow.textContent.includes('22.11.2026'),'GPS entry identifies train and recording date');gpsRow.querySelector('button').click();await until(()=>opened?.journey==='gps-track');assert(opened.id==='gps-report','GPS entry opens its report and journey');tracks=[];dispatchEvent(new Event('quality-sync-change'));await until(()=>document.querySelector('[data-quality-status]').dataset.syncState==='synced');


 RailDiagnostics.record('map.poland',12);RailDiagnostics.record('map.poland',19);RailDiagnostics.record('password=SUPERSECRET',99);RailDiagnostics.error('http',422);localStorage.setItem('private-record','PASSWORD SUPERSECRET GPS 52.456789 13.123456 PRIVATE_PERSONAL_TEXT');const data=JSON.stringify(await RailQuality.diagnosticPackage());assert(data.includes('0.28.12.16')&&data.includes('map.poland')&&data.includes('422'),'Technical diagnostics present');for(const value of ['SUPERSECRET','52.456789','13.123456','PRIVATE_PERSONAL_TEXT','synthetic-report'])assert(!data.includes(value),'No personal/secret field in diagnostics: '+value);assert(JSON.parse(data).personal_gps_included===false,'GPS excluded');
 document.querySelector('[data-quality-status] button:nth-child(2)').click();const d=[...document.querySelectorAll('dialog')].find(d=>d.open);assert(d&&d.textContent.includes('p95'),'Metrics visible before export');[...d.querySelectorAll('button')].at(-1).click();await until(()=>download);assert(download.name.endsWith('.json')&&!download.text.includes('SUPERSECRET'),'Explicit local export only');d.close();
 const host=document.getElementById('expiry');const view=await RailQuality.mountExpiry({id:11},host);await view.reload();assert(host.querySelectorAll('tr[data-knowledge-expiry]').length===3,'Owned expiry entries rendered');assert(host.querySelector('[data-knowledge-expiry=expired]').style.color,'Expired entry marked');own=12;const foreign=await RailQuality.mountExpiry({id:11},document.getElementById('foreign'));await foreign.reload();assert(!document.querySelector('#foreign [data-knowledge-expiry=expired]'),'Wrong owner response is rejected');
 parent.postMessage({layoutStatus:'pass'},'*');})().catch(e=>parent.postMessage({layoutStatus:'fail',message:e.stack},'*'));
'''
 return '<!doctype html><html><head><meta charset="utf-8"></head><body><header>Rail Software</header><main><div id="expiry"></div><div id="foreign"></div></main><script>'+setup+'</script>'+''.join('<script src="/tf/'+name+'"></script>' for name in ASSETS)+'<script>'+checks+'</script></body></html>'
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output-dir',required=True);a=p.parse_args();check_pages(fixture,a.output_dir,widths=(800,375),assets={'/tf/'+n:STATIC/n for n in ASSETS},label='Quality status and private diagnostics',timeout=30)
